import net.officefloor.plugin.variable.Val;

/** Edits the claim and releases its editor's lock, refusing when another user's editor locks it, or it is no longer a DRAFT, or is dated in a closed period, or would be moved into one,
 *  or would be dated after its person's retirement date, or would be a correction of no SETTLED claim of its person. */
public class ApplyClaim {
    public void apply(@Val ClaimValues values, @Val Claim claim, Sheets sheets, ClosedPeriods closedPeriods,
            People people, Claims claims)
            throws ClaimEditRefusedException, ClaimLockedException, PeriodClosedException, PersonRetiredException, InvalidSheetRequestException {
        ApplyClaimLock.refuseLocked(claim, values.user());
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ClaimEditRefusedException(claim.getStatus());
        }
        LocalDate date = values.date() != null ? values.date() : sheets.today(claim.getSheetId());
        closedPeriods.refuse(claim.getSheetId(), claim.getDate());
        closedPeriods.refuse(claim.getSheetId(), date);
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        if (person != null) person.refuseRetired(date);
        BuildClaim.refuseUncorrected(values, claim.getSheetId(), claim.getPersonId(), claims);
        claim.setAmount(values.amount());
        claim.setDate(date);
        claim.setNote(values.note());
        claim.setCorrects(values.corrects());
        claim.setLockedBy(null);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Builds the new claim, its due-by fixed from its person's own terms, else those of their grade in force on its date, a late entry when a soft-closed period contains its date, refusing one dated in a closed period or after its person's retirement date,
 *  and a correction that does not name a SETTLED claim of the same person. */
public class BuildClaim {
    public void build(@Val ClaimValues values, @Val Person person, Sheets sheets, ClosedPeriods closedPeriods,
            Claims claims, Settings settings, Out<Claim> claim) throws PeriodClosedException, PersonRetiredException, InvalidSheetRequestException {
        claim.set(built(values, person, sheets, closedPeriods, claims, settings));
    }

    /** The new DRAFT claim for these values and person, or refused by the claim form's rules. */
    static Claim built(ClaimValues values, Person person, Sheets sheets, ClosedPeriods closedPeriods,
            Claims claims, Settings settings) throws PeriodClosedException, PersonRetiredException, InvalidSheetRequestException {
        LocalDate date = values.date() != null ? values.date() : sheets.today(person.getSheetId());
        closedPeriods.refuse(person.getSheetId(), date);
        person.refuseRetired(date);
        refuseUncorrected(values, person.getSheetId(), person.getId(), claims);
        Claim built = new Claim(null, person.getSheetId(), person.getId(), values.amount(), date, values.note(),
                ClaimStatus.DRAFT, null, null, null);
        built.setCorrects(values.corrects());
        built.setDueBy(dueBy(person, date, settings));
        built.setLateEntry(closedPeriods.late(person.getSheetId(), date));
        return built;
    }

    /** The due-by of a claim of `person` dated `date`: its date plus the person's own terms, else
     *  the terms of their grade then, else the sheet's terms then. */
    static LocalDate dueBy(Person person, LocalDate date, Settings settings) {
        Integer own = person.getTerms();
        return date.plusDays(own != null ? own : settings.terms(person.getSheetId(), person.gradeOn(date), date));
    }

    /** Refuses a correction whose number is not a SETTLED claim of the same person. */
    static void refuseUncorrected(ClaimValues values, String sheetId, long personId, Claims claims)
            throws InvalidSheetRequestException {
        if (values.corrects() != null && !claims.settled(sheetId, personId, values.corrects())) {
            throw new InvalidSheetRequestException("A correction must name a settled claim of the same person: " + values.corrects());
        }
    }
}
